// Fagulho: Lendas do Bosque — assets.js
// Dois sprites embutidos em base64 (o jogo é um site estático de arquivos
// soltos: nada de fetch, nada de pasta de imagens):
//   * heitorHead (68x96) — rosto real do Heitor, recortado da foto com fade
//     no pescoço; o corpo é desenhado pelo player.js.
//   * bossDragon/Jaw/Snout (542x500, mesmo quadro) — o Dragão Escarlate, o
//     chefão do bosque, em TRÊS camadas de cutout: o corpo com a boca vazada,
//     a mandíbula (com o interior da boca) que gira na dobradiça, e o remendo
//     do focinho desenhado por cima — é atrás dele que a mandíbula desliza ao
//     fechar. Recortado do fundo azul da referência, virado para a esquerda,
//     que é de onde o jogador chega. As coordenadas notáveis (dobradiça,
//     boca, ponto fraco, eixo da reverência) vivem no boss1.js, junto de quem
//     as usa.
window.FG = window.FG || {};

(function () {
  var URI = 'data:image/png;base64,';
  var img;
  if (typeof Image !== 'undefined') {
    img = new Image();
    img.src = URI;
  } else {
    // ambiente sem DOM (testes headless): objeto inerte, nunca "carrega"
    img = { complete: false, naturalWidth: 0, naturalHeight: 0 };
  }
  // As três camadas do dragão partilham o quadro 542x500: desenhar as três na
  // mesma origem reconstitui a arte, e a rotação da mandíbula acontece em
  // coordenadas do quadro.
  function carrega(uri) {
    if (typeof Image === 'undefined') {
      // ambiente sem DOM (testes headless): objeto inerte, nunca "carrega"
      return { complete: false, naturalWidth: 0, naturalHeight: 0 };
    }
    var im = new Image();
    im.src = uri;
    return im;
  }
  var BODY_URI = 'data:image/png;base64,';
  var JAW_URI = 'data:image/png;base64,';
  var SNOUT_URI = 'data:image/png;base64,';
  var dragon = carrega(BODY_URI);
  var dragonJaw = carrega(JAW_URI);
  var dragonSnout = carrega(SNOUT_URI);

  FG.assets = {
    heitorHead: img,
    headRatio: 68 / 96,
    // As medidas do dragão (542x500) e os pontos notáveis dentro dele vivem no
    // boss1.js, num bloco só: são coordenadas DESTAS imagens, e trocar o sprite
    // é mexer nos dois lugares de uma vez.
    bossDragon: dragon,
    bossDragonJaw: dragonJaw,
    bossDragonSnout: dragonSnout,
  };
})();
